import { describe, it, expectTypeOf } from 'vitest';
import { FlexMap, FlexSet } from '../src/index';
import './test-utils';

describe('dictionaries and sets', () => {
    it('should allow use of a FlexSet as a Set', () => {
        const f = new FlexSet<string>(v => v);
        expectTypeOf(f).toExtend<Set<string>>();
    });

    it('should allow use of a FlexMap as a Map', () => {
        const f = new FlexMap<string, string>(v => v);
        expectTypeOf(f).toExtend<Map<string, string>>();
    });
});